function Remove-OldBackupFile {
    [CmdletBinding(SupportsShouldProcess)]
    param([string]$Path, [int]$RetentionDays = 14)

    Get-ChildItem $Path -Filter *.bak | ForEach-Object {
        if ($PSCmdlet.ShouldProcess($_.FullName, "Delete")) {
            Remove-Item $_.FullName
        }
    }
}
